import pandas as pd

def find_unrated_books(books: pd.DataFrame) -> pd.DataFrame:
    if books.empty:
        return pd.DataFrame(columns=['book_id', 'title', 'author', 'published_year'])
    unrated = books[books['rating'].isna()][['book_id', 'title', 'author', 'published_year']]
    return unrated.sort_values(by='book_id').reset_index(drop=True)
